def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find vertically separated bands containing the repeated figures.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # Compare same-height bands, marking differences in the lower copy.
    candidates = []
    for i, (a, b) in enumerate(bands):
        for c, d in bands[i + 1:]:
            if b - a != d - c:
                continue
            mismatch = sum(grid[a + k][x] != grid[c + k][x]
                           for k in range(b - a) for x in range(w))
            if mismatch:
                candidates.append((mismatch, a, b, c, d))

    if candidates:
        _, a, b, c, d = min(candidates)
        for k in range(b - a):
            for x in range(w):
                if grid[a + k][x] != grid[c + k][x]:
                    out[c + k][x] = 1
        return out

    # For isolated horizontal bars, extend the incomplete bar to match
    # the rightmost extent of the other bar(s).
    rows = [r for r in range(h) if any(v != bg for v in grid[r])]
    if len(rows) >= 2:
        max_end = max(max(x for x, v in enumerate(grid[r]) if v != bg)
                      for r in rows)
        for r in rows:
            end = max(x for x, v in enumerate(grid[r]) if v != bg)
            if end < max_end:
                for x in range(end + 1, w):
                    if grid[r][x] == bg:
                        out[r][x] = 1
    return out
