def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Divide the non-background pattern into horizontal bands.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # In repeated bands, extend the row with the shorter right edge to
    # the right edge of its matching row in the other band.
    for i, (a, b) in enumerate(bands):
        for c, d in bands[i + 1:]:
            if b - a != d - c:
                continue
            for k in range(b - a):
                row1, row2 = a + k, c + k
                cols1 = [x for x, v in enumerate(grid[row1]) if v != bg]
                cols2 = [x for x, v in enumerate(grid[row2]) if v != bg]
                if not cols1 or not cols2:
                    continue
                end1, end2 = max(cols1), max(cols2)
                if end1 < end2:
                    for x in range(end1 + 1, end2 + 1):
                        if grid[row1][x] == bg:
                            out[row1][x] = 1
                elif end2 < end1:
                    for x in range(end2 + 1, end1 + 1):
                        if grid[row2][x] == bg:
                            out[row2][x] = 1

    return out
